	// Smooth scroll-linked video scale (continuous rAF + lerp, driven outside Angular's zone)
	private readonly videoScaleMin = 0.5;
	private readonly videoScaleMax = 1;
	private currentVideoScale = 0.7;
	private targetVideoScale = 0.7;
	private videoScaleRafId: number | null = null;

	// Tracks the real cursor position so exiting fullscreen can resync hover state
	private lastMouseClientX = 0;
	private lastMouseClientY = 0;
	private readonly trackLastMousePosition = (event: MouseEvent): void => {
		this.lastMouseClientX = event.clientX;
		this.lastMouseClientY = event.clientY;
	};

	// Cursor-following "Play video" pill shown while hovering the video
	private hoverBtnTargetX = 0;
	private hoverBtnTargetY = 0;
	private hoverBtnCurrentX = 0;
	private hoverBtnCurrentY = 0;
	private hoverBtnRafId: number | null = null;

	private readonly handleVideoMouseMove = (event: MouseEvent): void => {
		const frame = this.videoFrame?.nativeElement;
		const btn = this.videoHoverBtn?.nativeElement;
		if (!frame || !btn) return;

		// frame.getBoundingClientRect() is in screen pixels, but the button's
		// translate3d() is applied inside .video-width-wrapper's own
		// `transform: scale(--video-scale)` — so a raw screen-pixel offset only
		// moves the button by offset * scale on screen. Divide out the scale so
		// the button tracks the cursor 1:1 instead of lagging behind it.
		const rect = frame.getBoundingClientRect();
		const scale = this.currentVideoScale || 1;
		this.hoverBtnTargetX = (event.clientX - rect.left) / scale - btn.offsetWidth / 2;
		this.hoverBtnTargetY = (event.clientY - rect.top) / scale - btn.offsetHeight / 2;
	};

	private readonly handleVideoMouseEnter = (event: MouseEvent): void => {
		this.videoFrame?.nativeElement.classList.add('is-hovering');
		this.handleVideoMouseMove(event);
		this.hoverBtnCurrentX = this.hoverBtnTargetX;
		this.hoverBtnCurrentY = this.hoverBtnTargetY;
		this.startHoverBtnLoop();
	};

	private readonly handleVideoMouseLeave = (): void => {
		this.videoFrame?.nativeElement.classList.remove('is-hovering');
		if (this.hoverBtnRafId !== null) {
			cancelAnimationFrame(this.hoverBtnRafId);
			this.hoverBtnRafId = null;
		}
	};

	private readonly handleVideoClick = (): void => {
		const inner = this.videoHoverBtnInner?.nativeElement;
		if (!inner) return;

		this.videoFrame?.nativeElement.classList.remove('is-hovering');
		inner.classList.remove('is-clicking');
		void inner.offsetWidth;
		inner.classList.add('is-clicking');
	};

	private readonly handleHoverBtnAnimationEnd = (): void => {
		this.videoHoverBtnInner?.nativeElement.classList.remove('is-clicking');
	};

	private startHoverBtnLoop(): void {
		if (this.hoverBtnRafId !== null) return;

		const step = () => {
			this.hoverBtnCurrentX += (this.hoverBtnTargetX - this.hoverBtnCurrentX) * 0.25;
			this.hoverBtnCurrentY += (this.hoverBtnTargetY - this.hoverBtnCurrentY) * 0.25;
			const btn = this.videoHoverBtn?.nativeElement;
			if (btn) {
				btn.style.transform = `translate3d(${this.hoverBtnCurrentX}px, ${this.hoverBtnCurrentY}px, 0)`;
			}
			this.hoverBtnRafId = requestAnimationFrame(step);
		};

		this.hoverBtnRafId = requestAnimationFrame(step);
	}

	private startVideoScaleLoop(): void {
		if (this.videoScaleRafId !== null) return;

		const step = () => {
			const scrollTop = window.scrollY || this.document.documentElement.scrollTop;
			this.targetVideoScale = Math.max(
				this.videoScaleMin,
				Math.min(this.videoScaleMax, this.videoScaleMin + scrollTop / 1000),
			);
			this.currentVideoScale += (this.targetVideoScale - this.currentVideoScale) * 0.12;
			this.applyVideoScale(this.currentVideoScale);

			this.videoScaleRafId = requestAnimationFrame(step);
		};

		this.videoScaleRafId = requestAnimationFrame(step);
	}

	private applyVideoScale(scale: number): void {
		this.videoWrapper?.nativeElement.style.setProperty('--video-scale', scale.toFixed(4));
	}

	private setupVideoHoverButton(): void {
		const video = this.videoElement?.nativeElement;
		if (!video) return;

		video.addEventListener('mousemove', this.handleVideoMouseMove);
		video.addEventListener('mouseenter', this.handleVideoMouseEnter);
		video.addEventListener('mouseleave', this.handleVideoMouseLeave);
		video.addEventListener('click', this.handleVideoClick);
		this.videoHoverBtnInner?.nativeElement.addEventListener('animationend', this.handleHoverBtnAnimationEnd);
	}

	private resyncVideoHoverState(video: HTMLVideoElement): void {
		const rect = video.getBoundingClientRect();
		const isOverVideo =
			this.lastMouseClientX >= rect.left &&
			this.lastMouseClientX <= rect.right &&
			this.lastMouseClientY >= rect.top &&
			this.lastMouseClientY <= rect.bottom;

		const syntheticEvent = { clientX: this.lastMouseClientX, clientY: this.lastMouseClientY } as MouseEvent;
		if (isOverVideo) {
			this.handleVideoMouseEnter(syntheticEvent);
		} else {
			this.handleVideoMouseLeave();
		}
	}

