	addFaqSchema() {
		if (!this.graphicsFaqs || this.graphicsFaqs.length === 0) return;

		const existingScript = this.document.getElementById('faq-schema-graphics');
		if (existingScript) {
			existingScript.remove();
		}

		const faqSchema = {
			"@context": "https://schema.org",
			"@type": "FAQPage",
			"mainEntity": this.graphicsFaqs.map((faq: any) => ({
				"@type": "Question",
				"name": faq.question,
				"acceptedAnswer": {
					"@type": "Answer",
					"text": faq.answer
				}
			}))
		};

		const script = this.document.createElement('script');
		script.type = 'application/ld+json';
		script.id = 'faq-schema-graphics';
		script.textContent = JSON.stringify(faqSchema);

		this.document.head.appendChild(script);
	}
	ngAfterViewInit() {
		if (!isPlatformBrowser(this.platformId)) return;
		const video = this.videoElement?.nativeElement;
		if (video) {
			video.muted = true;
			video.defaultMuted = true;
			video.volume = 0;
			video.play().catch(() => { });
		}

		this.ngZone.runOutsideAngular(() => {
			this.setupVideoHoverButton();
			window.addEventListener('mousemove', this.trackLastMousePosition, { passive: true });
		});

		this.applyVideoScale(this.currentVideoScale);
		this.ngZone.runOutsideAngular(() => {
			this.startVideoScaleLoop();
		});

		this.route.fragment.subscribe(fragment => {
			if (!fragment) return;

			const checkExist = setInterval(() => {
				const el = this.document.getElementById(fragment);

				if (el) {
					el.scrollIntoView({ behavior: 'smooth' });
					clearInterval(checkExist);
				}
			}, 300); // keep checking until element appears
		});
	}

	ngOnDestroy(): void {
		const video = this.videoElement?.nativeElement;
		if (video) {
			video.removeEventListener('mousemove', this.handleVideoMouseMove);
			video.removeEventListener('mouseenter', this.handleVideoMouseEnter);
			video.removeEventListener('mouseleave', this.handleVideoMouseLeave);
			video.removeEventListener('click', this.handleVideoClick);
		}
		this.videoHoverBtnInner?.nativeElement.removeEventListener(
			'animationend',
			this.handleHoverBtnAnimationEnd,
		);
		if (isPlatformBrowser(this.platformId)) {
			window.removeEventListener('mousemove', this.trackLastMousePosition);
		}
		if (this.hoverBtnRafId !== null) {
			cancelAnimationFrame(this.hoverBtnRafId);
			this.hoverBtnRafId = null;
		}
		if (this.videoScaleRafId !== null) {
			cancelAnimationFrame(this.videoScaleRafId);
			this.videoScaleRafId = null;
		}
	}

	getBannerdata() {
		const obj = {
			userUrl: '/services/graphics#packages',
			btnContent: 'Explore Packages',
			btnContent_ar: 'استكشف الباقات'

		};

		this.bannerService.getHomeBanner(obj).subscribe({
			next: (response: any) => {
				if (response?.code === 200 && response?.result?.length > 0) {
					this.bannerData = response.result
						.filter((item: any) => item.page === 'graphics-page')
						.map((item: any) => ({
							...item,
							userUrl: obj.userUrl,
							btnContent: obj.btnContent,
							btnContent_ar: obj.btnContent_ar
						}));

					this.hasBanner = this.bannerData.length > 0;
					this.cdr.markForCheck();
				}
			},
			error: (err) => {
				console.error('Banner API error:', err);
			}
		});
	}
	playVideoInModal(): void {
	if (!isPlatformBrowser(this.platformId)) return;

	const backgroundVideo = this.videoElement?.nativeElement;
	const modalVideo = this.modalVideoElement?.nativeElement;
	const modal = this.videoModal?.nativeElement;

	if (!backgroundVideo || !modalVideo || !modal) return;

	// Stop background video
	backgroundVideo.pause();

	// Open modal
	modal.classList.add('is-open');

	// Configure modal video
	modalVideo.muted = false;
	modalVideo.volume = 1;
	modalVideo.currentTime = 0;
	modalVideo.setAttribute('controls', '');

	// Play modal video
	modalVideo.play().catch(err => {
		console.log('Modal video play error:', err);
	});
}
closeVideoModal(): void {
	if (!isPlatformBrowser(this.platformId)) return;

	const backgroundVideo = this.videoElement?.nativeElement;
	const modalVideo = this.modalVideoElement?.nativeElement;
	const modal = this.videoModal?.nativeElement;

	if (!backgroundVideo || !modalVideo || !modal) return;

	// Stop modal video
	modalVideo.pause();
	modalVideo.currentTime = 0;

	// Close modal
	modal.classList.remove('is-open');

	// Resume background video
	backgroundVideo.muted = true;
	backgroundVideo.volume = 0;

	backgroundVideo.play().catch(err => {
		console.log('Background video resume error:', err);
	});
}
